import java.sql.*;import java.util.*;
public class JdbcBenchmark{
 static final String URL="jdbc:mysql://localhost:3306/assignment5",USER="root",PASS="YOUR_MYSQL_PASSWORD";
 static void clear(Connection c)throws SQLException{try(Statement s=c.createStatement()){s.executeUpdate("DELETE FROM bus_pass");}}
 static long statement(Connection c,int n)throws SQLException{clear(c);long t=System.nanoTime();try(Statement s=c.createStatement()){for(int i=1;i<=n;i++)s.executeUpdate("INSERT INTO bus_pass(pass_id,reg_no,name,route_no,amount) VALUES('P"+i+"','R"+i+"','Name"+i+"',"+(i%10)+","+(1000+i)+")");}return System.nanoTime()-t;}
 static long prepared(Connection c,int n)throws SQLException{clear(c);long t=System.nanoTime();try(PreparedStatement p=c.prepareStatement("INSERT INTO bus_pass(pass_id,reg_no,name,route_no,amount) VALUES(?,?,?,?,?)")){for(int i=1;i<=n;i++){p.setString(1,"P"+i);p.setString(2,"R"+i);p.setString(3,"Name"+i);p.setInt(4,i%10);p.setDouble(5,1000+i);p.executeUpdate();}}return System.nanoTime()-t;}
 static long batch(Connection c,int n)throws SQLException{clear(c);boolean old=c.getAutoCommit();c.setAutoCommit(false);long t=System.nanoTime();try(PreparedStatement p=c.prepareStatement("INSERT INTO bus_pass(pass_id,reg_no,name,route_no,amount) VALUES(?,?,?,?,?)")){for(int i=1;i<=n;i++){p.setString(1,"P"+i);p.setString(2,"R"+i);p.setString(3,"Name"+i);p.setInt(4,i%10);p.setDouble(5,1000+i);p.addBatch();if(i%1000==0)p.executeBatch();}p.executeBatch();c.commit();}catch(SQLException e){c.rollback();throw e;}finally{c.setAutoCommit(old);}return System.nanoTime()-t;}
 public static void main(String[] a){try(Scanner s=new Scanner(System.in);Connection c=DriverManager.getConnection(URL,USER,PASS)){System.out.print("Rows (1000/10000/100000): ");int n=s.nextInt();System.out.println("Statement ms: "+statement(c,n)/1e6);System.out.println("PreparedStatement ms: "+prepared(c,n)/1e6);System.out.println("Batch ms: "+batch(c,n)/1e6);}catch(Exception e){System.out.println("DB error: "+e.getMessage());}}
}
